excels.excel:

EXPORT WITH SHEET="工程项目进度款支付计划表", HEADER=true,
    MAPPING={"a":"工程节点","b":"计划完成日","c":"合同金额","d":"完成进度","e":"应付进度款","f":"已付金额","g":"待付金额"},
    FORMAT={"b":"yyyy-MM-dd","c":"#,##0.00","d":"0%","e":"#,##0.00","f":"#,##0.00","g":"#,##0.00"},
    FORMULAS={
        E2:'C2*D2',G2:'E2-F2', E3:'C3*D3',G3:'E3-F3', E4:'C4*D4',G4:'E4-F4',
        E5:'C5*D5',G5:'E5-F5', E6:'C6*D6',G6:'E6-F6', E7:'C7*D7',G7:'E7-F7',
        C8:'SUM(C2:C7)',E8:'SUM(E2:E7)',F8:'SUM(F2:F7)',G8:'E8-F8'
    },
    STYLE={
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        G4:{color:red,bold:true}
    }
